const displayTitle = (title: string|null|undefined) => {
  const value=title?.trim();
  if(!value)return 'Œuvre non résolue';
  const containsNonLatinLetters=[...value].some(character=>/\p{Letter}/u.test(character)&&!/\p{Script=Latin}/u.test(character));
  return containsNonLatinLetters?'Œuvre non résolue':value;
};
const itemDisplayTitle = (item: Pick<LibraryItem,'title'|'titleSelection'>) => displayTitle(item.titleSelection?.title ?? item.title);
const currentPath = () => typeof window === 'undefined' ? '/' : window.location.pathname;
const iconFor = (href: string) => href === '/' ? <House size={16} strokeWidth={1.8} /> : href === '/library' ? <LibraryBig size={16} strokeWidth={1.8} /> : href === '/calendar' ? <CalendarDays size={16} strokeWidth={1.8} /> : href === '/admin' ? <ShieldCheck size={16} strokeWidth={1.8} /> : <SettingsIcon size={16} strokeWidth={1.8} />;

function Shell({ children }: { children: React.ReactNode }) {
  const path = currentPath();
  const session=useApi<Session>('/api/v1/auth/session');
  const [notificationOpen,setNotificationOpen]=useState(false);
  const [reviewRefresh,setReviewRefresh]=useState(0);
  const reviewQueue=useApi<ReviewQueueSummary>('/api/v1/reviews',reviewRefresh);
  const [globalQuery,setGlobalQuery]=useState(()=>typeof window==='undefined'?'':new URLSearchParams(window.location.search).get('q')??'');
  const isAdmin=session.status==='ready'&&session.data?.user.role==='admin';
  const pendingReviews=reviewQueue.status==='ready'?reviewQueue.data?.pendingCount??0:0;
  const accountNav=[['/settings','Réglages'],...(isAdmin?[["/admin","Admin"]]:[])] as Array<[string,string]>;
  const goToSearch=(event:React.FormEvent)=>{event.preventDefault();window.location.href=globalQuery.trim()?`/library?q=${encodeURIComponent(globalQuery.trim())}`:'/library'};
  return <div className="app">
    <header className="site-header"><div className="header-inner"><a className="brand" href="/">Fav<span>Lib</span></a><nav className="nav primary-nav" aria-label="Navigation principale">{primaryNav.map(([href, label]) => <a className={path === href ? 'active' : ''} href={href} key={href}><span className="nav-icon">{iconFor(href)}</span>{label}</a>)}</nav><div className="header-center"><form className="global-search" role="search" onSubmit={goToSearch}><Search size={16} aria-hidden="true"/><input aria-label="Rechercher dans FavLib" placeholder="Rechercher dans FavLib" value={globalQuery} onChange={event=>setGlobalQuery(event.target.value)}/></form><div className="notification-wrap"><button className="notification-button" aria-label="Reviews à vérifier" aria-expanded={notificationOpen} onClick={()=>setNotificationOpen(value=>!value)}><Bell size={18} strokeWidth={1.8}/>{pendingReviews>0&&<span>{pendingReviews}</span>}</button>{notificationOpen&&<div className={`notification-panel${pendingReviews>0?' notification-panel-resolver':''}`}><strong>Reviews</strong>{pendingReviews>0?<NotificationResolver refreshKey={reviewRefresh} onDone={()=>setReviewRefresh(value=>value+1)}/>:reviewQueue.status==='loading'?<strong>Chargement…</strong>:reviewQueue.status==='error'?<strong>Impossible de charger les reviews.</strong>:reviewQueue.status==='unauthenticated'?<strong>Session expirée.</strong>:<strong>Aucune review à vérifier</strong>}</div>}</div></div><nav className="nav account-nav" aria-label="Compte">{accountNav.map(([href,label])=><a className={path===href?'active':''} href={href} key={href}><span className="nav-icon">{iconFor(href)}</span>{label}</a>)}<span className="avatar" aria-hidden="true"><UserRound size={15}/></span></nav></div></header>
    <main className="main">{children}</main>
    <nav className="mobile-nav" aria-label="Navigation mobile">{[...primaryNav,...accountNav].map(([href, label]) => <a className={path === href ? 'active' : ''} href={href} key={href}><span className="nav-icon">{iconFor(href)}</span>{label}</a>)}</nav>
  </div>;
}

function useApi<T>(url: string, revision = 0) {
  const [state, setState] = useState<{ status: ApiState; data: T | null }>({ status: 'loading', data: null });
  useEffect(() => {
    if (!url) return;
    let alive = true;
    void fetch(url).then(response => {
      if (response.status === 401) throw new Error('UNAUTHENTICATED');
      if (!response.ok) throw new Error(`HTTP_${response.status}`);
      return response.json() as Promise<T>;
    }).then(data => alive && setState({ status: 'ready', data })).catch(error => alive && setState({ status: error instanceof Error && error.message === 'UNAUTHENTICATED' ? 'unauthenticated' : 'error', data: null }));
    return () => { alive = false; };
  }, [url,revision]);
  return state;
}
function useMissingPositionRepair(items:LibraryItem[],refresh:()=>void){
  const attempted=useRef(new Set<string>());
  useEffect(()=>{
    const incomplete=items.map(item=>({mediaId:item.id,missing:[...(item.progress?[]:['personal'] as const),...(item.availability?[]:['availability'] as const)]})).filter(item=>item.missing.length);
    if(!incomplete.length)return;
    const signature=incomplete.map(item=>`${item.mediaId}:${item.missing.join(',')}`).sort().join('|');if(attempted.current.has(signature))return;attempted.current.add(signature);
    const controller=new AbortController(),timers:number[]=[];const csrf=window.localStorage.getItem('favlib-csrf')??'';
    void fetch('/api/v1/library/repair-missing-positions',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({items:incomplete}),signal:controller.signal}).then(async response=>response.ok?response.json() as Promise<RepairResult>:null).then(result=>{if(!result)return;if(result.items.some(item=>item.personal==='repaired'))refresh();if(result.items.some(item=>item.availability==='queued')){timers.push(window.setTimeout(refresh,2000),window.setTimeout(refresh,8000))}}).catch(error=>{if((error as Error).name!=='AbortError')return});
    return()=>{controller.abort();for(const timer of timers)window.clearTimeout(timer)};
  },[items,refresh]);
}
function useCalendarPages(url:string,loadAll:boolean){
  const [state,setState]=useState<{status:ApiState;data:{items:CalendarItem[];timeZone:string;facets:{genres:Facet[];categories:Facet[]}}|null}>({status:'loading',data:null});
  useEffect(()=>{let alive=true;setState({status:'loading',data:null});void (async()=>{try{let cursor:string|null=null;const items:CalendarItem[]=[];let timeZone='UTC';let facets={genres:[] as Facet[],categories:[] as Facet[]};do{const join=url.includes('?')?'&':'?';const response=await fetch(url+(cursor?`${join}cursor=${encodeURIComponent(cursor)}`:''));if(response.status===401)throw new Error('UNAUTHENTICATED');if(!response.ok)throw new Error(`HTTP_${response.status}`);const page=await response.json() as {items:CalendarItem[];timeZone:string;nextCursor:string|null;facets?:{genres:Facet[];categories:Facet[]}};items.push(...page.items);timeZone=page.timeZone;facets=page.facets??facets;cursor=loadAll?page.nextCursor:null}while(cursor);if(alive)setState({status:'ready',data:{items,timeZone,facets}})}catch(error){if(alive)setState({status:error instanceof Error&&error.message==='UNAUTHENTICATED'?'unauthenticated':'error',data:null})}})();return()=>{alive=false}},[url,loadAll]);return state;
}

function Header({ eyebrow, title, subtitle, actions }: { eyebrow: string; title: string; subtitle: string; actions?: React.ReactNode }) { return <div className="title-row"><div><div className="eyebrow">{eyebrow}</div><h1 className="title">{title}</h1><p className="subtitle">{subtitle}</p></div>{actions&&<div className="title-actions">{actions}</div>}</div>; }
function DataState({ state }: { state: ApiState }) { if (state === 'loading') return <div className="state">Chargement…</div>; if (state === 'unauthenticated') return <div className="state"><strong>Session requise.</strong><br />Connectez-vous pour accéder à vos données personnelles.<br /><a className="button primary" href="/login?next=%2Fsettings%23extension">Se connecter</a></div>; if (state === 'error') return <div className="state">Impossible de joindre l’API FavLib.</div>; return null; }
function PrivateLibraryGate() { return <section className="state"><span className="eyebrow">Liste personnelle</span><h2>Connexion requise</h2><p>Les favoris personnels sont disponibles uniquement dans votre session.</p><a className="button primary" href="/login?next=%2Flibrary">Se connecter</a></section>; }
function Cover({ item }: { item: Pick<LibraryItem, 'id' | 'title' | 'coverUrl'> }) { const [available, setAvailable] = useState(true); return available&&item.coverUrl ? <img src={item.coverUrl} alt={`Couverture ${displayTitle(item.title??'Œuvre')}`} loading="lazy" decoding="async" fetchPriority="low" width={600} height={900} onError={() => setAvailable(false)} /> : <span className="cover-placeholder" role="img" aria-label="Couverture indisponible">Couverture indisponible</span>; }
function CoverAttribution({value}:{value?:CoverProvenance|null}){if(!value)return null;const label=value.attribution??`Couverture : ${value.provider}`;return <a href={value.sourceUrl} target="_blank" rel="noreferrer">{label}</a>}
const statusLabel=(status:LibraryItem['status'])=>status??'';
function availabilityCounter(item:Pick<LibraryItem,'progress'|'availability'>){const personal=item.progress?.number??item.progress?.raw??'—';const available=item.availability?.number??item.availability?.raw??'—';return `${personal} / ${available}`}
function CardTopline({item}:{item:Pick<LibraryItem,'status'|'progress'|'availability'>}){return <div className="card-topline"><span>{statusLabel(item.status)}</span><strong>{availabilityCounter(item)}</strong></div>}
function cleanSynopsis(value:unknown){return typeof value==='string'?value.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim():null}
async function copyText(value:string){try{await navigator.clipboard.writeText(value);return}catch{}const field=document.createElement('textarea');field.value=value;field.readOnly=true;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('COPY_FAILED')}
function metadataValue(item:LibraryItem,key:string){const value=item.metadata?.metadata?.[key];if(typeof value==='string'||typeof value==='number')return String(value);return null}
function faviconCandidates(domain:string){const clean=domain.trim().toLowerCase();return clean?[`/api/v1/catalog/favicon?domain=${encodeURIComponent(clean)}`]:[]}
function DomainIcon({domain,fallback}:{domain:string;fallback?:string}){const candidates=faviconCandidates(domain);const [index,setIndex]=useState(0);if(!candidates[index])return fallback?<span className="media-source-favicon-fallback" title={fallback} aria-label={fallback}>{fallback}</span>:<span className="media-source-globe" title="Problème sur le lien"><Globe size={16} aria-label="Problème sur le lien"/></span>;return <img className="media-source-favicon" src={candidates[index]} alt="" aria-hidden="true" onError={()=>setIndex(value=>value+1)}/>}
function LanguageBadge({language}:{language?:string|null}){return language?<span className="source-language-badge" aria-label={`Langue ${language}`}>{language.split('-')[0].toUpperCase()}</span>:null}
function SourceIcon({source}:{source:LibrarySource}){return <span className="source-icon-wrap"><DomainIcon domain={source.domain} fallback={source.connector==='mangaupdates'?'MU':undefined}/><LanguageBadge language={source.language}/></span>}
