function favoritePosition(favorite:LibraryFavorite){const kind=typeof favorite.progression?.kind==='string'?favorite.progression.kind:'';const raw=favorite.progression?.raw??favorite.progression?.number;if(raw===undefined||raw===null)return null;return `${kind==='episode'?'Épisode':kind==='volume'?'Volume':'Chapitre'} ${String(raw)}`}
function uniqueFavorites(favorites:LibraryFavorite[]){return [...new Map(favorites.map(favorite=>[`${favorite.bookmarkId}:${favorite.url}`,favorite])).values()]}
function FavoriteRow({favorite}:{favorite:LibraryFavorite}){return <div className="media-source-row media-favorite-source-row"><a className="media-source-link" href={favorite.url} target="_blank" rel="noreferrer"><FavoriteIcon url={favorite.url}/><span><strong>{favorite.parsedTitle||'Titre parsé indisponible'}</strong>{favoritePosition(favorite)&&<small>{favoritePosition(favorite)}</small>}</span></a><div className="media-source-actions"><button type="button" className="icon-button" aria-label="Copier l’URL du favori" title="Copier l’URL du favori" onClick={()=>void copyText(favorite.url)}><Copy size={16}/></button></div></div>}
function SourceRow({item,source}:{item:LibraryItem;source:LibrarySource}){const [copied,setCopied]=useState(false);const [reported,setReported]=useState(false);const report=async()=>{const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch(`/api/v1/library/${encodeURIComponent(item.id)}/source-reports`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({mediaId:item.id,canonicalUrl:source.canonicalUrl,reason:'DEAD_LINK'})});if(response.ok)setReported(true)};const copy=async()=>{await copyText(source.canonicalUrl);setCopied(true);window.setTimeout(()=>setCopied(false),1800)};const state=sourceState(source);return <div className="media-source-row"><a className="media-source-link" href={source.canonicalUrl} target="_blank" rel="noreferrer"><SourceIcon source={source}/><span><strong>{sourceProvider(source)} · {source.title||source.domain}</strong>{source.chapter&&<small>Chapitre {source.chapter}</small>}</span></a><div className="media-source-actions">{state&&<span className={`media-source-state ${state[1]}`} title={source.status==='UNAVAILABLE'?'Site inaccessible':source.status==='MOVED'?'Lien déplacé':undefined}>{(source.status==='UNAVAILABLE'||source.status==='MOVED')&&<CircleAlert size={13} aria-hidden="true"/>}{state[0]}</span>}<button type="button" className="icon-button" aria-label="Signaler le lien" title="Signaler le lien" onClick={()=>void report()} disabled={reported}><CircleAlert size={16}/></button><button type="button" className="icon-button" aria-label={copied?'URL canonique copiée':'Copier l’URL canonique'} title="Copier l’URL canonique" onClick={()=>void copy()}><Copy size={16}/></button></div>{(copied||reported)&&<span className="media-source-confirmation" role="status">{copied?'URL canonique copiée.':'Signalement enregistré.'}</span>}</div>}
type RelatedWork={id:string;title:string|null;type:string;format?:string|null;seasonYear?:number|null;sequenceOrder:number|null;relationDepth?:number;relationTypes:string[];anilistId?:string|null;coverUrl:string|null;status?:LibraryItem['status'];progress?:LibraryItem['progress'];availability?:LibraryItem['availability']};
