function WorkHeaderIdentity({work,showContext=false}:{work:Pick<RelatedWork,'id'|'title'|'type'|'coverUrl'>;showContext?:boolean}){const related=work as RelatedWork;return <><span className="media-card-back-banner"><Cover item={work}/></span><span className="media-card-back-heading"><span className="media-card-heading-kicker"><strong>{work.type}</strong></span><h2>{displayTitle(work.title)}</h2>{showContext&&<small className="media-card-heading-context">{relatedWorkContext(related)}</small>}</span></>}
