const modalTabs=[{id:'links',label:'Liens'},{id:'info',label:'Informations'},{id:'similar',label:'Découvertes'}] as const;
type ContextFilter={kind:'author'|'studio';value:string};
function MediaCardBack({item:rootItem,onContextFilter}:{item:LibraryItem;onContextFilter?:(filter:ContextFilter)=>void}){
  const [tab,setTab]=useState<'links'|'info'|'similar'>('links');
  const [relatedOpen,setRelatedOpen]=useState(false);
  const [item,setItem]=useState(rootItem);const [loadingRelated,setLoadingRelated]=useState(false);const [relatedError,setRelatedError]=useState<string|null>(null);const [announcement,setAnnouncement]=useState('');
  const detailCache=useRef(new Map<string,LibraryItem>([[rootItem.id,rootItem]]));const requestSequence=useRef(0);
  const languagePreference=useApi<{preferredLanguages:string[]}>('/api/v1/preferences/languages');
  const preferredLanguages=languagePreference.status==='ready'&&languagePreference.data?.preferredLanguages?.length?languagePreference.data.preferredLanguages:(typeof navigator==='undefined'?[]:navigator.languages);
  // Language preferences rank recommendations; they must never hide a
  // source that was already attached to the user's work.
  const recommendedSources=(item.sources??[]).filter(source=>source.status==='AVAILABLE'&&Boolean(source.language)&&preferredLanguages.some(preferred=>languageMatches(preferred,source.language??null)));
  void recommendedSources;
  const modalRef=useRef<HTMLElement>(null);const checkedUrls=useRef(new Set<string>());const [,setSourceOverrides]=useState<Record<string,LibrarySource['status']>>({});
  useEffect(()=>{const host=modalRef.current?.closest('.physical-card');if(!host)return;const check=()=>{if(!host.classList.contains('is-modal-open'))return;for(const source of item.sources??[]){if(checkedUrls.current.has(source.canonicalUrl))continue;checkedUrls.current.add(source.canonicalUrl);const csrf=window.localStorage.getItem('favlib-csrf')??'';void fetch(`/api/v1/library/${encodeURIComponent(item.id)}/source-check`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({canonicalUrl:source.canonicalUrl})}).then(response=>response.ok?response.json() as Promise<{canonicalUrl:string;status:LibrarySource['status']}>:null).then(result=>{if(result)setSourceOverrides(previous=>{source.status=result.status;return {...previous,[result.canonicalUrl]:result.status}})}).catch(()=>undefined)}};check();const observer=new MutationObserver(check);observer.observe(host,{attributes:true,attributeFilter:['class']});return()=>observer.disconnect()},[item.id,item.sources]);
  const title=itemDisplayTitle(item);const description=cleanSynopsis(metadataValue(item,'description'));const relatedWorks=item.relatedWorks??[];
  const sameWork=relatedWorks.filter(work=>work.id===item.id||work.sequenceOrder!==null);const sameWorkIds=new Set(sameWork.map(work=>work.id));const discoveries=relatedWorks.filter(work=>work.id!==item.id&&!sameWorkIds.has(work.id)).slice(0,24);const hasRelated=sameWork.length>1;
  const plannedDate=item.latestReleaseDate;const planned=Boolean(plannedDate&&new Date(plannedDate).getTime()>Date.now());
  const selectWork=async(work:RelatedWork)=>{if(work.id===item.id||loadingRelated)return;setRelatedError(null);const cached=detailCache.current.get(work.id);if(cached){setItem(cached);setRelatedOpen(false);setTab('links');setAnnouncement(`Œuvre affichée : ${itemDisplayTitle(cached)}`);return}const sequence=++requestSequence.current;setLoadingRelated(true);try{const response=await fetch(`/api/v1/library/${encodeURIComponent(rootItem.id)}/related/${encodeURIComponent(work.id)}`);if(!response.ok)throw new Error(`HTTP_${response.status}`);const detail=await response.json() as LibraryItem;if(sequence!==requestSequence.current)return;detailCache.current.set(work.id,detail);setItem(detail);setRelatedOpen(false);setTab('links');setAnnouncement(`Œuvre affichée : ${itemDisplayTitle(detail)}`)}catch{if(sequence===requestSequence.current)setRelatedError('Impossible de charger cette œuvre. Le contenu affiché reste inchangé.')}finally{if(sequence===requestSequence.current)setLoadingRelated(false)}};
  const headerContents=<><WorkHeaderIdentity work={item}/>{hasRelated&&<ChevronDown className="media-related-chevron" size={19} aria-hidden="true"/>}</>;
  return <section ref={modalRef} className={`media-card-back-content${relatedOpen?' related-menu-open':''}`} aria-label={`Détails de ${title}`} aria-busy={loadingRelated}>
    <span className="sr-only" aria-live="polite">{announcement}</span>
    <header className={`media-card-back-header${hasRelated?' has-related-menu':''}`}>{hasRelated?<button data-modal-initial-focus type="button" className="media-card-related-toggle" aria-expanded={relatedOpen} aria-controls={`media-related-${item.id}`} onClick={()=>setRelatedOpen(value=>!value)}>{headerContents}</button>:headerContents}</header>
    {loadingRelated&&<span className="media-related-loading" role="status">Chargement…</span>}{relatedError&&<p className="media-related-error" role="alert">{relatedError}</p>}
    {relatedOpen?<div id={`media-related-${item.id}`} className="media-related-panel" role="region" aria-label="Saisons et parties de la même œuvre"><div className="media-related-list">{sameWork.map(work=><RelatedWorkRow work={work} currentId={item.id} onSelect={selectWork} key={work.id}/>)}</div></div>:<><div className="media-card-tabs" role="tablist" aria-label="Informations de l’œuvre">{modalTabs.map(({id,label},index)=><button data-modal-initial-focus={index===0&&!hasRelated?'true':undefined} key={id} type="button" role="tab" aria-selected={tab===id} aria-controls={`media-tab-${id}`} id={`media-tab-button-${id}`} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
    <div className="media-card-back-scroll">
    {tab==='links'&&<div id="media-tab-links" role="tabpanel" aria-labelledby="media-tab-button-links" className="media-card-tab-panel">{planned&&plannedDate&&<p className="media-card-notice"><strong>Prochaine sortie planifiée</strong><br/><time dateTime={plannedDate}>{new Date(plannedDate).toLocaleDateString('fr-FR')}</time></p>}<h3>Pages fournisseur</h3><div className="media-card-source-list">{providerPagesFor(item).map(page=><ProviderPageRow key={page.provider} page={page}/>)}</div><h3>Mes favoris</h3>{item.favorites?.length?<div className="media-card-source-list">{uniqueFavorites(item.favorites).map(favorite=><FavoriteRow favorite={favorite} key={`${favorite.bookmarkId}:${favorite.url}`}/>)}</div>:<p className="media-card-empty">Aucun favori personnel disponible.</p>}<h3>Sources validées</h3>{item.sources?.length?<div className="media-card-source-list">{(['anilist','mangaupdates'] as const).map(provider=>{const sources=item.sources?.filter(source=>source.connector===provider)??[];return sources.length?<section className="media-source-group" key={provider}><h4>{providerLabel(provider)}</h4>{sources.map(source=><SourceRow item={item} source={source} key={`${source.connector}-${source.canonicalUrl}`}/>)}</section>:null})}{(item.sources??[]).some(source=>source.connector!=='anilist'&&source.connector!=='mangaupdates')?<section className="media-source-group"><h4>Autres sources validées</h4>{item.sources.filter(source=>source.connector!=='anilist'&&source.connector!=='mangaupdates').map(source=><SourceRow item={item} source={source} key={`${source.connector}-${source.canonicalUrl}`}/>)}</section>:null}</div>:<p className="media-card-empty">Aucune source validée disponible.</p>}</div>}
      {tab==='info'&&<div id="media-tab-info" role="tabpanel" aria-labelledby="media-tab-button-info" className="media-card-tab-panel">{description?<p className="media-card-synopsis">{description}</p>:<p className="media-card-empty">Aucune description disponible.</p>}<dl className="media-card-details">{[['Type',item.type],['Format',item.format],['Année',item.seasonYear],['Épisodes AniList',item.type==='ANIME'?item.episodeTotal:null],['Langue',item.language],['Statut',item.status],['Genres',item.genres?.join(' · ')],['Catégories',item.categories?.join(' · ')],['Fournisseur',item.metadata?.provider]].map(([label,value])=>value?<div key={String(label)}><dt>{label}</dt><dd>{value}</dd></div>:null)}{item.authors?.length?<div><dt>Auteurs</dt><dd className="media-context-values">{item.authors.map(author=><button type="button" className="media-context-filter" title={`Provenance : ${author.provider}`} onClick={()=>onContextFilter?.({kind:'author',value:author.name})} key={`${author.provider}:${author.name}`}>{author.name}</button>)}</dd></div>:null}{item.studios?.length?<div><dt>Studios</dt><dd className="media-context-values">{item.studios.map(studio=><button type="button" className="media-context-filter" title={`Provenance : ${studio.provider}`} onClick={()=>onContextFilter?.({kind:'studio',value:studio.name})} key={`${studio.provider}:${studio.name}`}>{studio.name}</button>)}</dd></div>:null}</dl></div>}
      {tab==='similar'&&<div id="media-tab-similar" role="tabpanel" aria-labelledby="media-tab-button-similar" className="media-card-tab-panel">{discoveries.length?<div className="media-discovery-grid">{discoveries.map(work=><RelatedWorkCard work={work} onSelect={selectWork} key={work.id}/>)}</div>:<div className="media-card-empty media-card-similar-empty"><strong>Aucune autre série reliée</strong><span>Les relations prouvées apparaîtront ici lorsqu’elles seront disponibles.</span></div>}</div>}
    </div></>}
  </section>;
}
function MediaCard({ item,onContextFilter }: { item: LibraryItem;onContextFilter?:(filter:ContextFilter)=>void }) {const [session,setSession]=useState(0);const title=itemDisplayTitle(item);const poster=<div className="poster"><div className="poster-visual"><Cover item={item} /></div><CardTopline item={item}/><div className="poster-copy"><strong>{title}</strong><small>{item.type}</small></div></div>;return <PhysicalCard mode="media-modal" className="card media-card" label={`Aperçu de ${title}`} href={`/library/${encodeURIComponent(item.id)}`} front={poster} back={<MediaCardBack item={item} onContextFilter={onContextFilter} key={session}/>} onClose={()=>setSession(value=>value+1)}/>; }
function ContinueCard({item}:{item:LibraryItem}){const [session,setSession]=useState(0);const title=itemDisplayTitle(item);const front=<><div className="poster"><div className="poster-visual"><Cover item={item}/></div><CardTopline item={item}/><div className="poster-copy"><strong>{title}</strong><small>{item.type} · position {item.progress?.raw??'inconnue'}</small></div></div><div className="continue-progress"><span>Progression</span><strong>{item.progress?.raw??'—'}</strong></div></>;return <PhysicalCard mode="media-modal" className="card media-card continue-card" label={`Aperçu de ${title}`} href={`/library/${encodeURIComponent(item.id)}`} front={front} back={<MediaCardBack item={item} key={session}/>} onClose={()=>setSession(value=>value+1)}/>}

function PersonalShelf({ compact = false }: { compact?: boolean }) {
  const [revision,setRevision]=useState(0);const result = useApi<LibraryPage>(`/api/v1/library?limit=${compact?6:30}&offset=0`,revision);
  const items = result.data?.items ?? [];const refresh=useCallback(()=>setRevision(value=>value+1),[]);useMissingPositionRepair(items,refresh);
  if (result.status === 'unauthenticated') return <PrivateLibraryGate />;
  if (result.status !== 'ready') return <DataState state={result.status} />;
  if (!items.length) return <div className="state">Aucun favori n’est encore disponible. La synchronisation se fera automatiquement.</div>;
  return <div className="media-grid shelf-grid" data-testid="personal-shelf">{(compact ? items.slice(0, 6) : items).map(item => <MediaCard item={item} key={item.id} />)}</div>;
}
function ContinueShelf(){const result=useApi<LibraryPage>('/api/v1/library?limit=30&offset=0&sort=inventory&direction=asc');if(result.status==='unauthenticated')return <PrivateLibraryGate/>;if(result.status!=='ready')return <DataState state={result.status}/>;const items=(result.data?.items??[]).filter(item=>Boolean(item.progress));return items.length?<div className="media-grid shelf-grid continue-grid" data-testid="continue-shelf">{items.slice(0,6).map(item=><ContinueCard item={item} key={item.id}/>)}</div>:<div className="state">Aucune progression de lecture importée.</div>}

function inventoryStatus(item:InventoryItem){if(item.classificationStatus==='review'||item.linkStatus==='review')return 'À classer';if(item.classificationStatus==='recognized'||item.linkStatus==='matched'||item.linkStatus==='accepted')return 'Classé';return 'Favori importé'}
function InventoryRecommendationRow({recommendation}:{recommendation:InventoryRecommendation}){return <a className="media-source-link" href={recommendation.canonicalUrl} target="_blank" rel="noreferrer"><DomainIcon domain={recommendation.domain}/><span><strong>{recommendation.domain}</strong><small>{recommendation.language?`Langue ${recommendation.language}`:'Langue non déclarée'} · {recommendation.status==='INACCESSIBLE'?'Site inaccessible':recommendation.status==='AVAILABLE'?'Disponible':'État inconnu'}</small></span></a>}
function RawInventory(){const [items,setItems]=useState<InventoryItem[]>([]);const [total,setTotal]=useState(0);const [nextOffset,setNextOffset]=useState(0);const [hasMore,setHasMore]=useState(false);const [status,setStatus]=useState<ApiState>('loading');const [loadingMore,setLoadingMore]=useState(false);const load=useCallback(async(offset:number)=>{if(offset>0)setLoadingMore(true);try{const response=await fetch(`/api/v1/library/inventory?limit=100&offset=${offset}`);if(response.status===401){setStatus('unauthenticated');return}if(!response.ok)throw new Error();const page=await response.json() as InventoryPage;setItems(current=>offset? [...current,...page.items]:page.items);setTotal(page.total);setNextOffset(page.nextOffset);setHasMore(page.hasMore);setStatus('ready')}catch{setStatus('error')}finally{setLoadingMore(false)}},[]);useEffect(()=>{void load(0)},[load]);if(status==='unauthenticated')return <PrivateLibraryGate/>;if(status!=='ready')return <DataState state={status}/>;return <section className="card inventory-panel" data-testid="raw-inventory"><div className="section-head"><div><h2>Favoris importés</h2><span>{total} favori(s) non supprimé(s), indépendamment du classement</span></div></div>{items.length?<><div className="panel-list">{items.map(item=><article className="panel-item inventory-item" key={`${item.installationId}:${item.bookmarkId}`}><div><strong>{item.rawTitle||item.parsedTitle||'Favori sans titre'}</strong><small>{inventoryStatus(item)} · {item.rawUrl}</small></div><div className="inventory-recommendations">{item.recommendations.map(recommendation=><InventoryRecommendationRow key={recommendation.canonicalUrl} recommendation={recommendation}/>)}</div></article>)}</div>{hasMore&&<button className="load-more" type="button" disabled={loadingMore} onClick={()=>void load(nextOffset)}>{loadingMore?'Chargement…':'Afficher davantage de favoris'}</button>}</>:<p className="state">Aucun favori importé.</p>}</section>}

type FilterKey='type'|'genre'|'category'|'status'|'contentRating'|'demographic';
type FacetState='include'|'exclude';
type Selections=Record<FilterKey,Record<string,FacetState>>;
const filterKeys:FilterKey[]=['type','genre','category','status','contentRating','demographic'];
const emptySelections=():Selections=>({type:{},genre:{},category:{},status:{},contentRating:{},demographic:{}});
function initialLibraryState(){const params=typeof window==='undefined'?new URLSearchParams():new URLSearchParams(window.location.search);const selected=emptySelections();for(const key of filterKeys){for(const value of params.getAll(key))selected[key][value]='include';for(const value of params.getAll(`exclude${key[0].toUpperCase()}${key.slice(1)}`))selected[key][value]='exclude'}return {query:params.get('q')??'',sort:params.get('sort')&&params.get('direction')?`${params.get('sort')}:${params.get('direction')}`:'inventory:asc',selected,contextual:{author:params.getAll('author'),studio:params.getAll('studio')}};}
function MultiFacet({label,values,selected,onChange}:{label:string;values:Facet[]|undefined;selected:Record<string,FacetState>;onChange:(next:Record<string,FacetState>)=>void}){
  const visible=(values??[]).filter(item=>item.count>0||selected[String(item.value)]);
  if(!visible.length)return null;
  const toggle=(value:string)=>{const next={...selected};if(!next[value])next[value]='include';else if(next[value]==='include')next[value]='exclude';else delete next[value];onChange(next)};
  const count=Object.keys(selected).length;
  return <details className="multi-facet"><summary aria-label={`Filtrer par ${label.toLocaleLowerCase()}`}>{label}{count?` (${count})`:''}</summary><div className="facet-menu">{visible.map(item=>{const value=String(item.value),state=selected[value];return <button type="button" className={`facet-option${state?` ${state}`:''}`} aria-label={`${value} : ${state==='include'?'inclus':state==='exclude'?'exclu':'neutre'}`} aria-pressed={Boolean(state)} onClick={()=>toggle(value)} key={value}><span className="facet-state" aria-hidden="true">{state==='include'?'✓':state==='exclude'?'−':''}</span><span>{value}</span><small>{item.count}</small></button>})}</div></details>;
}

function Library() {
  const initial=useRef(initialLibraryState());
  const [query,setQuery]=useState(initial.current.query);const [sort,setSort]=useState(initial.current.sort);const [selected,setSelected]=useState<Selections>(initial.current.selected);const [contextual,setContextual]=useState(initial.current.contextual);
  const [status,setStatus]=useState<ApiState>('loading');
  const [items,setItems]=useState<LibraryItem[]>([]);
  const [total,setTotal]=useState(0);
  const [nextOffset,setNextOffset]=useState(0);
  const [hasMore,setHasMore]=useState(false);
  const [loadingMore,setLoadingMore]=useState(false);
  const requestId=useRef(0);
  useEffect(()=>{
    const closeOutside=(event:PointerEvent)=>{for(const menu of document.querySelectorAll<HTMLDetailsElement>('details.multi-facet[open]'))if(!menu.contains(event.target as Node))menu.open=false};
    const closeOthers=(event:Event)=>{const opened=event.target as HTMLDetailsElement;if(!opened.matches?.('details.multi-facet')||!opened.open)return;for(const menu of document.querySelectorAll<HTMLDetailsElement>('details.multi-facet[open]'))if(menu!==opened)menu.open=false};
    document.addEventListener('pointerdown',closeOutside);document.addEventListener('toggle',closeOthers,true);
    return()=>{document.removeEventListener('pointerdown',closeOutside);document.removeEventListener('toggle',closeOthers,true)};
  },[]);
  const filterParams=()=>{const params=new URLSearchParams();if(query.trim())params.set('q',query.trim());for(const key of filterKeys)for(const [value,state] of Object.entries(selected[key]))params.append(state==='include'?key:`exclude${key[0].toUpperCase()}${key.slice(1)}`,value);for(const kind of ['author','studio'] as const)for(const value of contextual[kind])params.append(kind,value);return params;};
  const facets=useApi<LibraryFacets>(`/api/v1/library/facets?${filterParams()}`);
  const load=async(offset:number,replace:boolean,signal?:AbortSignal)=>{const id=++requestId.current;if(!replace)setLoadingMore(true);try{const [sortKey,direction]=sort.split(':');const params=filterParams();params.set('limit','30');params.set('offset',String(offset));params.set('sort',sortKey);params.set('direction',direction);const response=await fetch(`/api/v1/library?${params}`,{signal});if(response.status===401){if(id===requestId.current)setStatus('unauthenticated');return}if(!response.ok)throw new Error(`HTTP_${response.status}`);const page=await response.json() as LibraryPage;if(id!==requestId.current)return;setItems(current=>replace?page.items:[...new Map([...current,...page.items].map(item=>[item.id,item])).values()]);setTotal(page.total);setNextOffset(page.nextOffset);setHasMore(page.hasMore);setStatus('ready');}catch(error){if((error as Error).name!=='AbortError'&&id===requestId.current)setStatus('error')}finally{if(id===requestId.current)setLoadingMore(false)}};
  const repairRefresh=useCallback(()=>{void load(0,true)},[query,selected,contextual,sort]);useMissingPositionRepair(items,repairRefresh);
  useEffect(()=>{const params=filterParams();const [sortKey,direction]=sort.split(':');if(sortKey!=='inventory'||direction!=='asc'){params.set('sort',sortKey);params.set('direction',direction)}const next=params.toString()?`${window.location.pathname}?${params}`:window.location.pathname;window.history.replaceState(null,'',next);// URL intentionally follows every local filter change.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[query,selected,contextual,sort]);
  useEffect(()=>{const controller=new AbortController();setNextOffset(0);setHasMore(false);const timer=window.setTimeout(()=>{setStatus(current=>current==='ready'?'ready':'loading');void load(0,true,controller.signal)},200);return()=>{window.clearTimeout(timer);controller.abort()};// load intentionally captures the current search query.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[query,selected,contextual,sort]);
  if (status === 'unauthenticated') return <div className="content"><Header eyebrow="Collection personnelle" title="Bibliothèque" subtitle="Favoris privés issus de PostgreSQL" /><PrivateLibraryGate /></div>;
  if (status !== 'ready') return <div className="content"><Header eyebrow="Collection personnelle" title="Bibliothèque" subtitle="Votre bibliothèque issue de PostgreSQL" /><DataState state={status} /></div>;
  const data=facets.data;const setFilter=(key:FilterKey,next:Record<string,FacetState>)=>setSelected(current=>({...current,[key]:next}));const addContextFilter=({kind,value}:ContextFilter)=>setContextual(current=>({...current,[kind]:current[kind].includes(value)?current[kind]:[...current[kind],value]}));const removeContextFilter=({kind,value}:ContextFilter)=>setContextual(current=>({...current,[kind]:current[kind].filter(item=>item!==value)}));const reset=()=>{setQuery('');setSelected(emptySelections());setContextual({author:[],studio:[]});setSort('inventory:asc')};
  return <div className="content"><Header eyebrow="Collection personnelle" title="Bibliothèque" subtitle={`${total} œuvre${total === 1 ? '' : 's'} classée${total === 1 ? '' : 's'}`} /><div className="toolbar library-filters"><input className="input" aria-label="Rechercher dans la bibliothèque" placeholder="Rechercher…" value={query} onChange={event => setQuery(event.target.value)} /><MultiFacet label="Types" values={data?.types} selected={selected.type} onChange={next=>setFilter('type',next)}/><MultiFacet label="Genres" values={data?.genres} selected={selected.genre} onChange={next=>setFilter('genre',next)}/><MultiFacet label="Catégories" values={data?.categories} selected={selected.category} onChange={next=>setFilter('category',next)}/><MultiFacet label="Statuts" values={data?.statuses} selected={selected.status} onChange={next=>setFilter('status',next)}/><MultiFacet label="Classifications" values={data?.contentRatings} selected={selected.contentRating} onChange={next=>setFilter('contentRating',next)}/><MultiFacet label="Démographies" values={data?.demographics} selected={selected.demographic} onChange={next=>setFilter('demographic',next)}/><select className="select" aria-label="Trier la bibliothèque" value={sort} onChange={event=>setSort(event.target.value)}><option value="inventory:asc">Ordre stable</option><option value="title:asc">Titre A → Z</option><option value="title:desc">Titre Z → A</option><option value="type:asc">Type A → Z</option><option value="type:desc">Type Z → A</option><option value="release:desc">Dernière sortie récente → ancienne</option><option value="release:asc">Ordre de sortie ancien → récent</option><option value="favorites:desc">Nombre de favoris décroissant</option></select><button className="button ghost" type="button" onClick={reset}>Réinitialiser</button></div>{contextual.author.length||contextual.studio.length?<div className="library-context-filters" aria-label="Filtres actifs">{(['author','studio'] as const).flatMap(kind=>contextual[kind].map(value=><button type="button" className="library-context-chip" aria-label={`Retirer le filtre ${kind==='author'?'auteur':'studio'} ${value}`} onClick={()=>removeContextFilter({kind,value})} key={`${kind}:${value}`}>{kind==='author'?'Auteur':'Studio'} : {value} ×</button>))}</div>:null}{items.length ? <><div className="media-grid shelf-grid" data-testid="library-grid">{items.map(item => <MediaCard item={item} onContextFilter={addContextFilter} key={item.id} />)}</div>{hasMore&&<button className="load-more" disabled={loadingMore} onClick={()=>void load(nextOffset,false)}>{loadingMore?'Chargement…':'Voir plus'}</button>}</> : <div className="state">Aucune œuvre classée ne correspond à ces filtres.</div>}</div>;
}

function Home() {
  const timeZone=typeof Intl==='undefined'?'UTC':Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
  const releases=useApi<{items:CalendarItem[]}>('/api/v1/calendar/latest');
  const items=[...(releases.data?.items??[])].sort((a,b)=>new Date(b.startsAtUtc).getTime()-new Date(a.startsAtUtc).getTime()).slice(0,6);
  return <div className="content"><Header eyebrow="Accueil" title="Votre bibliothèque" subtitle="Données publiques et liste personnelle séparées" /><div className="section-head"><h2>Ma liste</h2><a className="see-more" href="/library">Voir toute ma liste →</a></div><PersonalShelf compact /><div className="section-head continue-head"><h2>À continuer</h2><span>Progression personnelle</span></div><ContinueShelf/><div className="section-head"><h2>Dernières sorties</h2><a className="see-more" href="/calendar">Voir le calendrier →</a></div>{releases.status!=='ready'?<DataState state={releases.status}/>:items.length?<div className="release-grid calendar-release-grid">{items.map(item=><CalendarEventCard item={item} timeZone={timeZone} key={`${item.category}-${item.mediaId}-${item.releaseKey}`}/>)}</div>:<div className="state">Aucune sortie récente pour vos favoris.</div>}</div>;
}

function CalendarEventCard({item,timeZone}:{item:CalendarItem;timeZone:string}) {
  const releaseLabel=releaseCalendarLabel(item);
  const facets=[...(item.genres??[]),...(item.categories??[])].slice(0,3);
  const front=<div className="poster"><div className="poster-visual"><Cover item={{id:item.mediaId,title:item.personalTitle??item.title,coverUrl:item.coverUrl??null}}/></div><div className="card-topline">{item.timePrecision==='INSTANT'?<time dateTime={item.startsAtUtc} title="Heure de diffusion">{calendarCardDate(item.startsAtUtc,timeZone)}</time>:<span aria-hidden="true"/>}<strong>{releaseLabel}</strong></div><div className="poster-copy"><strong>{displayTitle(item.personalTitle??item.title)}</strong><small>{[item.type,...facets].join(' · ')}</small></div></div>;return <PhysicalCard mode="media-modal" className="card media-card calendar-media-card" label={`Aperçu de ${displayTitle(item.personalTitle??item.title)}`} href={`/library/${encodeURIComponent(item.mediaId)}`} front={front} back={null}/>;
}

function Detail({ id }: { id: string }) {
  const result = useApi<DetailItem>(`/api/v1/library/${encodeURIComponent(id)}`);
  if (result.status !== 'ready') return <div className="content"><DataState state={result.status} /></div>;
  const item = result.data!;
  const catalog=item.metadata?.metadata??{};const localized=(catalog.descriptions??catalog.description) as unknown;const descriptions=localized&&typeof localized==='object'&&!Array.isArray(localized)?localized as Record<string,unknown>:null;const browserLanguages=typeof navigator==='undefined'?[]:navigator.languages.map(value=>value.toLocaleLowerCase());const descriptionValue=descriptions?[...browserLanguages,'en',...Object.keys(descriptions).sort()].map(language=>descriptions[language]??descriptions[language.split('-')[0]]).find(value=>typeof value==='string'):catalog.description;const description=typeof descriptionValue==='string'?descriptionValue.replace(/<[^>]+>/g,' '):null;const genres=Array.isArray(catalog.genres)?catalog.genres.filter((value):value is string=>typeof value==='string'):[];const categories=Array.isArray(catalog.categories)?catalog.categories.filter((value):value is string=>typeof value==='string'):[];
  return <div className="content"><Header eyebrow="Bibliothèque / œuvre" title={displayTitle(item.title)} subtitle={`${item.type}${item.seasonYear ? ` · ${item.seasonYear}` : ''}`} />{item.bannerUrl&&<div className="detail-banner"><img src={item.bannerUrl} alt="" loading="eager" decoding="async" /><span><CoverAttribution value={item.bannerProvenance}/></span></div>}<div className="detail-hero"><div className="detail-poster"><Cover item={item} /></div><div className="detail-copy"><h2>{displayTitle(item.title)}</h2><p>{item.favoriteCount} favori{item.favoriteCount === 1 ? '' : 's'} rattaché{item.favoriteCount === 1 ? '' : 's'} à cette œuvre.</p><p>Résolution : <strong>{item.metadata?.status ?? 'FALLBACK'}</strong>{item.metadata?.provider ? ` · ${item.metadata.provider}` : ''}</p><p><CoverAttribution value={item.coverProvenance}/></p>{genres.length>0&&<p className="metadata-tags"><strong>Genres :</strong> {genres.join(' · ')}</p>}{categories.length>0&&<p className="metadata-tags"><strong>Catégories :</strong> {categories.join(' · ')}</p>}{description&&<p>{description}</p>}</div></div><section className="card"><h2>Favoris associés</h2><div className="panel-list">{item.favorites.map(favorite => <div className="panel-item" key={favorite.bookmarkId}><div><strong>{favorite.title||'Favori sans titre'}</strong><small>{favorite.device} · {favorite.url}</small></div></div>)}</div></section></div>;
}

function Calendar() {
  const [type,setType]=useState(''); const [genreSelection,setGenreSelection]=useState<Record<string,FacetState>>({}); const [categorySelection,setCategorySelection]=useState<Record<string,FacetState>>({}); const [search,setSearch]=useState(''); const [visibleRows,setVisibleRows]=useState(5);
  const [favoritesOnly,setFavoritesOnly]=useState(true);
  const [weekOffset,setWeekOffset]=useState(0);
  const browserTimeZone=typeof Intl==='undefined'?'UTC':Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
  useEffect(()=>setVisibleRows(5),[weekOffset,type,favoritesOnly]);
  const currentWeekStart=startOfWeek(new Date(),0);
  const weekStart=addDays(currentWeekStart,weekOffset*7);
  const weekEnd=addDays(weekStart,7);
  const includedGenres=Object.entries(genreSelection).filter(([,state])=>state==='include').map(([value])=>value);const includedCategories=Object.entries(categorySelection).filter(([,state])=>state==='include').map(([value])=>value);
  const query=[type&&'type='+type,includedGenres.length&&`genre=${encodeURIComponent(includedGenres.join(','))}`,includedCategories.length&&`metadataCategory=${encodeURIComponent(includedCategories.join(','))}`,`favorites=${favoritesOnly}`,`from=${encodeURIComponent(weekStart.toISOString())}`,`to=${encodeURIComponent(weekEnd.toISOString())}`].filter(Boolean).join('&');
  const calendarQuery=[query,`timezone=${encodeURIComponent(browserTimeZone)}`].filter(Boolean).join('&');
  const result = useCalendarPages(`/api/v1/calendar?${calendarQuery}`,!favoritesOnly);
  if (result.status !== 'ready') return <div className="content"><Header eyebrow="Planning personnel" title="Calendrier" subtitle="Sorties datées associées à vos favoris" /><DataState state={result.status} /></div>;
  const timeZone=result.data?.timeZone??'UTC';
  const needle=search.trim().toLocaleLowerCase();
  const excludedGenres=Object.entries(genreSelection).filter(([,state])=>state==='exclude').map(([value])=>value.toLocaleLowerCase());const excludedCategories=Object.entries(categorySelection).filter(([,state])=>state==='exclude').map(([value])=>value.toLocaleLowerCase());
  const items=(result.data?.items??[]).filter(item=>(!needle||[item.title,item.personalTitle,...(item.genres??[]),...(item.categories??[])].some(value=>value?.toLocaleLowerCase().includes(needle)))&&!item.genres?.some(value=>excludedGenres.includes(value.toLocaleLowerCase()))&&!item.categories?.some(value=>excludedCategories.includes(value.toLocaleLowerCase())));
  const days=Array.from({length:7},(_,index)=>addDays(weekStart,index));
  const eventsFor=(day:Date)=>items.filter(item=>calendarDateKey(item.startsAtUtc,timeZone)===calendarDateKey(day.toISOString(),timeZone)).sort(calendarEventOrder);
  const maxRows=Math.max(0,...days.map(day=>eventsFor(day).length));
  const rangeLabel=`${weekStart.toLocaleDateString('fr-FR',{day:'numeric',month:'short'})} – ${days[6].toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'})}`;
  const searchBox=<input className="input" type="search" aria-label="Rechercher dans le calendrier" placeholder="Titre, genre ou catégorie…" value={search} onChange={event=>{setSearch(event.target.value);setVisibleRows(5)}}/>;
  return <div className="content"><Header eyebrow="Planning personnel" title="Calendrier" subtitle={'Fuseau : '+(result.data?.timeZone??'UTC')+' · les horaires gardent leur instant UTC'} actions={searchBox}/>
    <div className="toolbar calendar-filters"><select className="select" aria-label="Choisir le contenu du calendrier" value={favoritesOnly?'favorites':'all'} onChange={event=>{setFavoritesOnly(event.target.value==='favorites');setWeekOffset(0)}}><option value="favorites">Mes favoris uniquement</option><option value="all">Tout le catalogue</option></select><select className="select" aria-label="Filtrer par type de média" value={type} onChange={event=>{setType(event.target.value);setWeekOffset(0)}}><option value="">Tous les médias</option><option value="ANIME">Anime</option><option value="MANGA">Manga</option><option value="MANHWA">Manhwa</option><option value="MANHUA">Manhua</option></select><MultiFacet label="Genres" values={result.data?.facets.genres} selected={genreSelection} onChange={next=>{setGenreSelection(next);setVisibleRows(5)}}/><MultiFacet label="Catégories" values={result.data?.facets.categories} selected={categorySelection} onChange={next=>{setCategorySelection(next);setVisibleRows(5)}}/><button className="button ghost" type="button" onClick={()=>{setFavoritesOnly(true);setType('');setGenreSelection({});setCategorySelection({});setWeekOffset(0)}}>Réinitialiser</button></div>
    <div className="week-toolbar"><button className="button ghost" type="button" disabled={weekOffset<=-2} onClick={()=>setWeekOffset(value=>Math.max(-2,value-1))}>← Semaine précédente</button><strong>{weekOffset===0?'Cette semaine':rangeLabel}</strong><button className="button ghost" type="button" disabled={weekOffset>=2} onClick={()=>setWeekOffset(value=>Math.min(2,value+1))}>Semaine suivante →</button></div>
    <div className="week-list">{days.map(day=>{const dayItems=eventsFor(day).slice(0,visibleRows);const isToday=calendarDateKey(day.toISOString(),timeZone)===calendarDateKey(new Date().toISOString(),timeZone);return <section className={`planning-day-row${isToday?' today':''}`} key={day.toISOString()}><header><strong>{day.toLocaleDateString('fr-FR',{weekday:'long'})}</strong><span>{day.toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}</span></header>{dayItems.length?<div className="planning-row-cards">{dayItems.map(item=><CalendarEventCard item={item} timeZone={timeZone} key={item.category+'-'+item.mediaId+'-'+item.releaseKey}/>)}</div>:null}</section>})}</div>{visibleRows<maxRows&&<button className="load-more" type="button" onClick={()=>setVisibleRows(value=>Math.min(maxRows,value+5))}>Voir plus</button>}
  </div>;
}

function addDays(date:Date,days:number){const next=new Date(date);next.setDate(next.getDate()+days);return next;}
function startOfWeek(date:Date,offset:number){const start=new Date(date);const day=start.getDay()||7;start.setHours(0,0,0,0);start.setDate(start.getDate()-day+1+(offset*7));return start;}
function calendarDateKey(value:string,timeZone:string){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));const get=(name:string)=>parts.find(part=>part.type===name)?.value??'';return `${get('year')}-${get('month')}-${get('day')}`;}
function calendarCardDate(value:string,timeZone:string){return new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone}).format(new Date(value));}
function calendarEventOrder(left:CalendarItem,right:CalendarItem){const leftAnime=left.timePrecision==='INSTANT',rightAnime=right.timePrecision==='INSTANT';if(leftAnime!==rightAnime)return leftAnime?-1:1;if(leftAnime)return new Date(left.startsAtUtc).getTime()-new Date(right.startsAtUtc).getTime()||displayTitle(left.personalTitle??left.title).localeCompare(displayTitle(right.personalTitle??right.title),'fr');return displayTitle(left.personalTitle??left.title).localeCompare(displayTitle(right.personalTitle??right.title),'fr');}
function releaseCalendarLabel(item:{chapter?:string|null;chapterDisplay?:string|null;volume?:string|null}){const parts=[item.volume&&`Volume ${item.volume}`,item.chapterDisplay??(item.chapter&&`Chapitre ${item.chapter}`)].filter(Boolean);return parts.length?parts.join(' · '):'Nouvelle release';}

function CalendarFeeds() {
  const feeds=useApi<{items:Array<{id:string;label:string;url:string|null;revokedAt:string|null}>}>('/api/v1/calendar/feeds');
  const [open,setOpen]=useState(false);
  const [message,setMessage]=useState('');
  const request=async(path:string,method:'POST'|'DELETE'='POST')=>{const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch(path,{method,headers:{'X-CSRF-Token':csrf,'Content-Type':'application/json'},body:method==='POST'?JSON.stringify({label:'FavLib',filters:{}}):undefined});if(!response.ok){setMessage('Impossible de modifier le flux.');return}if(method==='DELETE'){window.location.reload();return}const data=await response.json() as {url?:string};if(data.url){await navigator.clipboard?.writeText(data.url);setMessage('URL privée copiée. Conservez-la : le jeton ne sera plus affiché.')}};
  return <section className="card setting-summary"><span className="eyebrow">Flux ICS privé</span><h2>Calendrier externe</h2><p>{feeds.status==='ready'?`${feeds.data?.items.filter(feed=>!feed.revokedAt).length??0} flux actif(s)`:'Chargement…'}</p><button className="button" type="button" onClick={()=>setOpen(true)}>Gérer</button>{open&&<div className="settings-modal" role="dialog" aria-modal="true" aria-label="Réglages du calendrier externe"><div className="settings-modal-card"><div className="settings-modal-head"><div><span className="eyebrow">Flux ICS privé</span><h2>Calendrier externe</h2></div><button className="button ghost" onClick={()=>setOpen(false)}>Fermer</button></div><p>Copiez une URL privée dans votre client de calendrier. Vous pourrez la régénérer ou la révoquer ici.</p><button className="button primary" type="button" onClick={()=>void request('/api/v1/calendar/feeds')}>Créer et copier un flux</button>{message&&<p role="status">{message}</p>}{feeds.status==='ready'&&<div className="panel-list">{feeds.data?.items.map(feed=><div className="panel-item" key={feed.id}><div><strong>{feed.label}</strong><small>{feed.revokedAt?'Révoqué':'Actif · URL secrète affichée une seule fois'}</small></div>{!feed.revokedAt&&<div className="admin-actions"><button className="button" type="button" onClick={()=>void request('/api/v1/calendar/feeds/'+feed.id+'/regenerate')}>Régénérer et copier</button><button className="button danger" type="button" onClick={()=>void request('/api/v1/calendar/feeds/'+feed.id,'DELETE')}>Révoquer</button></div>}</div>)}</div>}</div></div>}</section>;
}

function ContentPreferences(){const preference=useApi<{allowAdult:boolean}>('/api/v1/preferences/content');const [message,setMessage]=useState('');const save=async(allowAdult:boolean)=>{const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch('/api/v1/preferences/content',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({allowAdult})});setMessage(response.ok?'Préférence enregistrée.':'Impossible d’enregistrer la préférence.');if(response.ok)window.location.reload()};return <section className="card setting-summary"><span className="eyebrow">Affichage</span><h2>Tags adultes</h2><p>Tous les favoris restent importés et visibles. Cette option contrôle uniquement les tags explicitement marqués adultes par le fournisseur.</p>{preference.status==='ready'?<label className="setting-toggle"><input type="checkbox" defaultChecked={preference.data?.allowAdult??false} onChange={event=>void save(event.target.checked)}/> Afficher les tags et catégories adultes</label>:<DataState state={preference.status}/>} {message&&<small role="status">{message}</small>}</section>}
function LanguagePreferences(){const preference=useApi<{preferredLanguages:string[]}>('/api/v1/preferences/languages');const initial=typeof navigator==='undefined'?[]:navigator.languages.map(language=>language.replace('_','-'));const [languages,setLanguages]=useState<string[]>(initial);const [newLanguage,setNewLanguage]=useState('');useEffect(()=>{if(preference.status==='ready')setLanguages(preference.data?.preferredLanguages?.length?preference.data.preferredLanguages:initial)},[preference.status,preference.data]);const save=async(next:string[])=>{setLanguages(next);const csrf=window.localStorage.getItem('favlib-csrf')??'';await fetch('/api/v1/preferences/languages',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({preferredLanguages:next})})};return <section className="card setting-summary"><span className="eyebrow">Recommandations</span><h2>Langues préférées</h2><p>Les sources disponibles sont recommandées selon ces langues. Les codes régionaux, comme en-US, correspondent à en.</p><div className="language-preference-list">{languages.map(language=><button type="button" className="badge" key={language} onClick={()=>void save(languages.filter(value=>value!==language))} aria-label={`Retirer ${language}`}>{language.toUpperCase()} ×</button>)}</div><form onSubmit={event=>{event.preventDefault();const value=newLanguage.trim().replace('_','-');if(value&&!languages.includes(value))void save([...languages,value]);setNewLanguage('')}}><input className="input" aria-label="Ajouter une langue" placeholder="fr ou en-US" value={newLanguage} onChange={event=>setNewLanguage(event.target.value)}/><button className="button" type="submit">Ajouter</button></form></section>}
const languageChoices='ar bg ca cs da de el en es et eu fa fi fr ga he hi hr hu id is it ja ko lt lv ms nl no pl pt ro ru sk sl sv sw th tr uk vi zh'.split(' ');
function languageFlag(language:string){const primary=language.toLowerCase().split('-')[0];const region=({ar:'sa',bg:'bg',ca:null,cs:'cz',da:'dk',de:'de',el:'gr',en:'gb',es:'es',et:'ee',eu:null,fa:'ir',fi:'fi',fr:'fr',ga:'ie',he:'il',hi:'in',hr:'hr',hu:'hu',id:'id',is:'is',it:'it',ja:'jp',ko:'kr',lt:'lt',lv:'lv',ms:'my',nl:'nl',no:'no',pl:'pl',pt:'pt',ro:'ro',ru:'ru',sk:'sk',sl:'si',sv:'se',sw:'ke',th:'th',tr:'tr',uk:'ua',vi:'vn',zh:'cn'} as Record<string,string|null>)[primary];return region?<span className={`fi fi-${region} language-flag-svg`} aria-hidden="true"/>:<span className="language-flag-fallback" aria-hidden="true">🌐</span>}
function languageName(language:string){try{return new Intl.DisplayNames(['fr'],{type:'language'}).of(language.split('-')[0])??language}catch{return language}}
function LanguagePreferencesV2(){const preference=useApi<{preferredLanguages:string[]}>('/api/v1/preferences/languages');const browserLanguages=typeof navigator==='undefined'?[]:Array.from(navigator.languages);const [languages,setLanguages]=useState<string[]>(browserLanguages);const [open,setOpen]=useState(false);useEffect(()=>{if(preference.status==='ready'&&preference.data?.preferredLanguages?.length)setLanguages(preference.data.preferredLanguages)},[preference.status,preference.data]);const save=async(next:string[])=>{setLanguages(next);const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch('/api/v1/preferences/languages',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({preferredLanguages:next})});if(response.ok)setOpen(false)};const toggle=(language:string)=>void save(languages.some(value=>value.split('-')[0]===language)?languages.filter(value=>value.split('-')[0]!==language):[...languages,language]);return <section className="card setting-summary language-settings"><span className="eyebrow">Recommandations</span><h2>Langues préférées</h2><p>Les sources disponibles sont recommandées selon ces langues. Le code et le drapeau indiquent le filtre actif.</p><details className="language-picker" open={open} onToggle={event=>setOpen((event.currentTarget as HTMLDetailsElement).open)}><summary><span className="language-picker-value">{languages.length?languages.map(language=><span className="language-chip" key={language}><span aria-hidden="true">{languageFlag(language)}</span><strong>{language.split('-')[0].toUpperCase()}</strong></span>):<span className="language-picker-placeholder">Choisir des langues</span>}</span><ChevronDown size={16} aria-hidden="true"/></summary><div className="language-picker-menu" role="group" aria-label="Langues disponibles">{languageChoices.map(language=><button type="button" className={`language-option${languages.some(value=>value.split('-')[0]===language)?' selected':''}`} aria-pressed={languages.some(value=>value.split('-')[0]===language)} onClick={()=>toggle(language)} key={language}><span aria-hidden="true">{languageFlag(language)}</span><span>{languageName(language)}</span><strong>{language.toUpperCase()}</strong></button>)}</div></details></section>}

function hashPairingCode() {
  if (typeof window === 'undefined') return '';
  return new URLSearchParams(window.location.hash.replace(/^#extension&?/, '')).get('code') ?? '';
}

function Settings() {
  const session = useApi<{ user: { email: string } }>('/api/v1/auth/session');
  const devices = useApi<{ items: Device[] }>('/api/v1/extension/devices');
  const challenge = typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('pairing') : null;
  const [open, setOpen] = useState(Boolean(challenge));
  const [devicesOpen,setDevicesOpen]=useState(false);
  const [code, setCode] = useState(hashPairingCode);
  const [message, setMessage] = useState(challenge && code ? 'Confirmation automatique en cours…' : 'Installez puis liez chaque profil de navigateur à ce compte.');
  const attempted = useRef(false);

  const confirmPairing = async () => {
    if (!challenge || !/^\d{8}$/.test(code)) { setMessage('Saisissez le code à 8 chiffres affiché par l’extension.'); return; }
    setMessage('Confirmation de l’appairage…');
    const csrf = window.localStorage.getItem('favlib-csrf') ?? '';
    const response = await fetch(`/api/v1/extension/pairing/challenges/${challenge}/confirm`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, body: JSON.stringify({ code, browser: navigator.userAgent.slice(0, 40), name: 'Profil FavLib' }) });
    const body = await response.json().catch(() => null);
    setMessage(response.ok ? 'Extension liée. L’import reprend automatiquement dans le popup.' : response.status === 403 ? 'Session expirée : reconnectez-vous, puis revenez sur ce lien.' : body?.error?.message ?? 'Appairage impossible.');
  };
  const revokeDevice=async(id:string)=>{const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch(`/api/v1/extension/devices/${encodeURIComponent(id)}/revoke`,{method:'POST',headers:{'X-CSRF-Token':csrf}});if(response.ok)window.location.reload();else setMessage('Impossible de révoquer ce profil.')};

  useEffect(() => {
    if (session.status === 'ready' && challenge && /^\d{8}$/.test(code) && !attempted.current) { attempted.current = true; void confirmPairing(); }
  // confirmPairing intentionally runs once for the challenge carried by the extension.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session.status, challenge, code]);

  if (session.status === 'loading') return <div className="content"><DataState state="loading" /></div>;
  if (session.status !== 'ready') {
    const next = typeof window === 'undefined' ? '/settings#extension' : window.location.pathname + window.location.search + window.location.hash;
    return <div className="content"><Header eyebrow="Compte" title="Réglages" subtitle="Session FavLib" /><div className="state"><strong>Session requise.</strong><br />Connectez-vous : la demande et le code d’appairage seront conservés.<br /><a className="button primary" href={`/login?next=${encodeURIComponent(next)}`}>Se connecter</a></div></div>;
  }

  return <div className="content"><Header eyebrow="Compte" title="Réglages" subtitle={`Session de ${session.data?.user.email}`} />
    <div className="settings-grid"><CalendarFeeds />
      <section className="card extension-install" id="extension"><div><span className="eyebrow">Extension FavLib</span><h2>Installation et appairage</h2><p className={message.includes('impossible') || message.includes('expirée') ? 'setting-error' : ''}>{message}</p></div><button className="button primary" onClick={() => setOpen(value => !value)}>{open ? 'Masquer les étapes' : 'Afficher les étapes'}</button>{open && <div className="install-guides"><section><span className="eyebrow">1 · Installer</span><h3>Télécharger l’extension</h3><div className="guide-actions"><a className="button primary" href="/downloads/favlib-extension-chrome.zip" download>Chrome</a><a className="button" href="/downloads/favlib-extension-firefox.zip" download>Firefox</a></div></section><section><span className="eyebrow">2 · Lier</span><h3>Depuis le popup FavLib</h3><p>Cliquez « Appairer ce profil ». Cette page s’ouvre avec le code et confirme automatiquement. En secours, saisissez-le ci-dessous.</p>{challenge ? <div className="pairing-form"><label htmlFor="pairing-code">Code d’appairage</label><input className="input" id="pairing-code" inputMode="numeric" maxLength={8} pattern="[0-9]{8}" placeholder="8 chiffres" value={code} onChange={event => setCode(event.target.value)} /><button className="button primary" onClick={() => void confirmPairing()}>Confirmer</button></div> : <small>Démarrez l’appairage depuis le popup de l’extension.</small>}</section></div>}</section>
      <section className="card setting-summary"><span className="eyebrow">Appareils</span><h2>Profils liés</h2><p>{devices.status==='ready'?`${devices.data?.items.filter(device=>!(device.revokedAt??device.revoked_at)).length??0} profil(s) actif(s)`:'Chargement…'}</p><button className="button" onClick={()=>setDevicesOpen(true)}>Gérer</button>{devicesOpen&&<div className="settings-modal" role="dialog" aria-modal="true" aria-label="Profils liés"><div className="settings-modal-card"><div className="settings-modal-head"><div><span className="eyebrow">Appareils</span><h2>Profils liés</h2></div><button className="button ghost" onClick={()=>setDevicesOpen(false)}>Fermer</button></div>{devices.status !== 'ready' ? <p className="setting-error">Impossible de lire les appareils.</p> : devices.data?.items.length ? <div className="device-list">{devices.data.items.map(device => { const revoked = device.revokedAt ?? device.revoked_at; const verified = device.verifiedSyncAt ?? device.verified_sync_at; return <div className="device-row" key={device.id}><div><strong>{device.name} · profil {device.installationIdShort??String(device.installationId??device.installation_id??'').slice(-8)}</strong><small>{revoked ? 'Révoqué' : 'Actif'} · synchronisation vérifiée {verified ? new Date(verified).toLocaleString('fr-FR') : 'jamais'}</small><small>{device.inventoryTotal} inventorié(s) · {device.recognizedCount} reconnu(s) · {device.reviewCount} à vérifier · {device.excludedCount} exclu(s)</small></div>{revoked?<span className="badge error">Révoqué</span>:<button className="button danger" onClick={()=>void revokeDevice(device.id)}>Révoquer</button>}</div>; })}</div> : <p>Aucun profil lié.</p>}</div></div>}</section>
      <ContentPreferences/><LanguagePreferencesV2/>
    </div>
  </div>;
}

type ReviewCandidate={id:string;providerId:string;displayTitle:string;canonicalTitle:string;hitTitle?:string|null;matchedAlias?:string|null;associatedTitles?:string[];type?:string;format?:string;year?:number;authors?:unknown;categories?:string[];genres?:string[];image?:string|null;url:string};
type ReviewData={id:string;clusterId?:string|null;favoriteCount?:number;favoriteTitle:string;sourceTitle?:string|null;rawFavoriteTitle?:string|null;progression?:{kind:string;number:number;raw:string}|null;favoriteUrl:string;provider:string;status:string;reason?:string|null;candidates:ReviewCandidate[];google:{anilist:string;mangaupdates:string}};
const candidateDisplayTitle=(candidate:ReviewCandidate)=>candidate.displayTitle?.trim()||candidate.hitTitle?.trim()||candidate.canonicalTitle;
function ReviewCandidateCard({candidate,compact=false,onResolve}:{candidate:ReviewCandidate;compact?:boolean;onResolve:()=>void}){
  const title=candidateDisplayTitle(candidate);
  const back=<div className="physical-card-back-actions"><button className="review-card-action" type="button" onClick={onResolve}><span>Ajouter</span></button><a className="review-card-action" href={candidate.url} target="_blank" rel="noreferrer"><span>Source de l’œuvre</span></a></div>;
  if(compact){const front=<div className="poster">{candidate.image?<img src={candidate.image} alt=""/>:<span className="cover-placeholder">Couverture indisponible</span>}<div className="poster-copy"><strong>{title}</strong><small>{[candidate.type,candidate.year].filter(Boolean).join(' · ')||'Informations limitées'}</small></div></div>;return <PhysicalCard mode="review-hover" className="card media-card notification-choice" label={title} front={front} back={back}/>}
  const front=<article className="review-candidate card"><div className="review-cover">{candidate.image?<img src={candidate.image} alt="" loading="lazy"/>:<span>Image indisponible</span>}</div><div className="review-candidate-body"><span className="eyebrow">{candidate.providerId}</span><h2>{title}</h2><p className="review-meta">{[candidate.year,candidate.format,candidate.type,candidate.authors?JSON.stringify(candidate.authors):null].filter(Boolean).join(' · ')}</p>{candidate.genres?.length?<p className="review-tags"><strong>Genres :</strong> {candidate.genres.slice(0,5).join(' · ')}</p>:null}{candidate.categories?.length?<p className="review-tags"><strong>Catégories :</strong> {candidate.categories.slice(0,5).join(' · ')}</p>:null}</div></article>;
  return <PhysicalCard mode="review-hover" className="review-candidate-shell" label={title} front={front} back={back}/>;
}
const reviewReasonLabel=(reason?:string|null)=>({NO_RESULT:'Aucun résultat fournisseur retourné.',TYPE_MISMATCH:'Les résultats retournés ne correspondent pas au type attendu.',FORMAT_MISMATCH:'Les résultats retournés ne correspondent pas au format attendu.',LOW_CONFIDENCE:'Des candidats existent, mais aucun matching déterministe n’a été établi.',AMBIGUOUS:'Plusieurs correspondances restent possibles.'}[reason??'']??'Correspondance à vérifier.');
const manualReviewBody=(provider:string,value:string)=>{const input=value.trim();return {provider,id:/^https?:\/\//u.test(input)?undefined:input,url:/^https?:\/\//u.test(input)?input:undefined}};
function VerifyButton({busy,className='button'}:{busy:boolean;className?:string}){
  const [dots,setDots]=useState(1);
  useEffect(()=>{if(!busy){setDots(1);return}const timer=window.setInterval(()=>setDots(value=>value===3?1:value+1),420);return()=>window.clearInterval(timer)},[busy]);
  return <button className={`${className} verify-action`} type="submit" disabled={busy} aria-busy={busy} aria-label={busy?'Vérification en cours':'Vérifier'}><span aria-hidden={busy}>{busy?`Vérifier${'.'.repeat(dots)}`:'Vérifier'}</span></button>;
}
function NotificationResolver({refreshKey,onDone}:{refreshKey:number;onDone:()=>void}){
  type QueueItem={id:string;favoriteTitle:string;favoriteUrl:string;provider:string;status:string;candidateCount:number};
  const queue=useApi<{items:QueueItem[];pendingCount:number}>(`/api/v1/reviews?resolver=${refreshKey}`);
  const pending=(queue.data?.items??[]).filter(item=>item.status==='PENDING');
  const first=pending[0];
  const detail=useApi<ReviewData>(first?`/api/v1/reviews/${encodeURIComponent(first.id)}`:'');
  const [manual,setManual]=useState(''); const [manualOpen,setManualOpen]=useState(false); const [message,setMessage]=useState(''); const [manualPending,setManualPending]=useState(false);
  const manualRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(!manualOpen)return; const frame=window.requestAnimationFrame(()=>manualRef.current?.scrollIntoView({block:'nearest',behavior:'smooth'})); return()=>window.cancelAnimationFrame(frame)},[manualOpen]);
  const csrf=()=>window.localStorage.getItem('favlib-csrf')??'';
  const decide=async(path:string,body?:unknown)=>{if(!first)return;if(path==='manual')setManualPending(true);setMessage(path==='manual'?'Mise en file…':'Enregistrement…');const response=await fetch(`/api/v1/reviews/${encodeURIComponent(first.id)}/${path}`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json().catch(()=>null);if(path==='manual')setManualPending(false);if(response.ok){setManual('');setManualOpen(false);setMessage(path==='manual'?'Vérification enregistrée dans la file.':'Correspondance enregistrée.');onDone()}else setMessage(result?.error?.message??'Action impossible.')};
  if(!first)return queue.status==='ready'?null:<div className="notification-resolver-loading">Chargement de la file…</div>;
  if(detail.status==='loading')return <div className="notification-resolver-loading">Chargement des correspondances…</div>;
  if(detail.status==='unauthenticated')return <div className="notification-resolver-loading">Session expirée. Reconnectez-vous pour consulter les correspondances.</div>;
  if(detail.status==='error')return <div className="notification-resolver-loading">Impossible de charger les correspondances. Réessayez dans quelques instants.</div>;
  const review=detail.data!;
  return <section className="notification-resolver"><div className="notification-resolver-head"><div><h2>Correspondances à résoudre</h2></div></div><div className="notification-resolver-favorite"><div><strong>{review.favoriteTitle}</strong><small>{review.provider==='anilist'?'AniList':'MangaUpdates'} · {review.favoriteCount&&review.favoriteCount>1?`${review.favoriteCount} favoris regroupés`:'titre original du favori'}</small></div><a href={review.favoriteUrl} target="_blank" rel="noreferrer">Source ↗</a></div><p className="notification-resolver-question">Quelle œuvre correspond à ce favori&nbsp;?</p><div className="notification-choice-grid">{review.candidates.map(candidate=><ReviewCandidateCard compact candidate={candidate} key={candidate.id} onResolve={()=>void decide('resolve',{candidateId:candidate.id})}/>)}<button type="button" className={`card media-card notification-choice notification-choice-plus${manualOpen?' selected':''}`} onClick={()=>setManualOpen(value=>!value)} aria-expanded={manualOpen}><div className="poster"><Plus size={48} strokeWidth={1.5} aria-hidden="true"/></div></button></div>{manualOpen&&<div className="notification-manual" ref={manualRef}><a className="button" href={review.google[review.provider as 'anilist'|'mangaupdates']} target="_blank" rel="noreferrer">Google ↗</a><form onSubmit={event=>{event.preventDefault();if(!manualPending)void decide('manual',manualReviewBody(review.provider,manual))}}><input className="input" aria-label="ID ou URL fournisseur" placeholder="ID ou URL AniList / MangaUpdates" value={manual} onChange={event=>setManual(event.target.value)} disabled={manualPending} required/><VerifyButton busy={manualPending} className="button primary"/></form></div>}<div className="notification-resolver-footer">{message&&<span>{message}</span>}</div></section>;
}

function Review({id,position,total,embedded=false,onClose,onDone}:{id:string;position?:number;total?:number;embedded?:boolean;onClose?:()=>void;onDone?:()=>void}) {
  const result=useApi<ReviewData>(`/api/v1/reviews/${encodeURIComponent(id)}`); const [message,setMessage]=useState(''); const [manual,setManual]=useState(''); const [manualPending,setManualPending]=useState(false);
  const csrf=()=>window.localStorage.getItem('favlib-csrf')??'';
  const decide=async(path:string,body?:unknown)=>{if(path==='manual')setManualPending(true);setMessage(path==='manual'?'Mise en file…':'Enregistrement…');const r=await fetch(`/api/v1/reviews/${encodeURIComponent(id)}/${path}`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf()},body:body===undefined?undefined:JSON.stringify(body)});const b=await r.json().catch(()=>null);if(path==='manual')setManualPending(false);setMessage(r.ok?(path==='manual'?'Vérification enregistrée dans la file.':'Décision enregistrée.'):b?.error?.message??'Action impossible.');if(r.ok){if(onDone)onDone();else window.location.href='/review'}};
  if(!id||result.status!=='ready') return embedded?<div className="review-embedded-loading"><DataState state={result.status}/></div>:<div className="content"><Header eyebrow="Resolver" title="Correspondance à vérifier" subtitle="Chargement des candidats…"/><DataState state={result.status}/></div>;
  const review=result.data!; const frame=embedded?'review-embedded':'content review-page'; return <div className={frame}><div className="review-toolbar"><div><span className="eyebrow">Resolver{position&&total?` · ${position}/${total}`:''}</span><h1 className="title">Correspondance à vérifier</h1><p className="subtitle">Une question à la fois, sans quitter vos notifications.</p></div>{onClose?<button className="button review-close-action" onClick={onClose}>Fermer</button>:<a className="button" href="/">Fermer</a>}</div><section className="review-source card"><div className="review-source-label"><span className="eyebrow">Favori original</span><a href={review.favoriteUrl} target="_blank" rel="noreferrer">Ouvrir la page source ↗</a></div><h2>{review.favoriteTitle}</h2><p>{review.provider==='anilist'?'AniList':'MangaUpdates'} · les cartes affichent le titre fournisseur le plus proche du favori{review.favoriteCount&&review.favoriteCount>1?` · ${review.favoriteCount} favoris regroupés`:''}.</p></section><section className="review-question-head"><div><span className="eyebrow">Candidats fournisseur</span><h2>Quelle œuvre correspond ?</h2></div><span className="review-count">{review.candidates.length} candidat{review.candidates.length===1?'':'s'}</span></section>{review.candidates.length?<div className="review-grid">{review.candidates.map(candidate=><ReviewCandidateCard candidate={candidate} key={candidate.id} onResolve={()=>void decide('resolve',{candidateId:candidate.id})}/>)}</div>:<section className="review-empty card"><div className="review-empty-icon">?</div><div><h2>Aucun candidat confirmé</h2><p>La recherche fournisseur n’a pas retourné de fiche fiable. Recherchez une variante puis vérifiez son identifiant ou son URL.</p></div></section>}<section className="review-manual card"><div><span className="eyebrow">Autre piste</span><h2>Vous ne reconnaissez aucun candidat ?</h2><p>Recherchez le titre exact puis collez un identifiant ou une URL fournisseur vérifiée.</p></div><div className="review-manual-actions"><a className="button" href={review.google[review.provider as 'anilist'|'mangaupdates']} target="_blank" rel="noreferrer">Rechercher sur Google ↗</a><form onSubmit={event=>{event.preventDefault();if(!manualPending)void decide('manual',manualReviewBody(review.provider,manual))}}><input className="input" aria-label="Identifiant ou URL fournisseur" placeholder="ID ou URL fournisseur" value={manual} onChange={event=>setManual(event.target.value)} disabled={manualPending} required/><VerifyButton busy={manualPending}/></form></div><button className="button danger ghost" onClick={()=>void decide('no-match')} disabled={manualPending}>Aucun ne correspond</button>{message&&<p className="review-message" role="status">{message}</p>}</section></div>;
}

function Admin(){
  type AdminUser={id:string;email:string;role:'admin'|'member';active:boolean;devices:number;lastSyncAt:string|null};
  type SettingResponse={values:Record<string,number>;defaults:Record<string,number>};
  const metrics=useApi<{users:number;activeDevices:number;pendingJobs:number;staleSnapshots:number;unreadNotifications:number}>('/api/v1/admin/metrics');
  const session=useApi<{user:{email:string;role:string}}>('/api/v1/auth/session');
  const users=useApi<{items:AdminUser[];total:number}>('/api/v1/admin/users');
  const invitations=useApi<{items:Array<{id:string;email:string;expiresAt:string;consumedAt:null|string;revokedAt:null|string}>}>('/api/v1/admin/invitations');
  const providers=useApi<{items:Array<{provider:string;status:string;version:string;attribution?:string;lastResult?:string;lastAttemptAt?:string;backoffUntil?:string}>}>('/api/v1/admin/metadata-provider-policies');
  const sources=useApi<{items:Array<{id:string;domain:string;state:string;activeVersion?:string;versions:unknown[]}>}>('/api/v1/admin/sources');
  const backups=useApi<{items:Array<{id:string;status:string;requestedAt:string;checksum?:string;rpo:string;rto:string}>}>('/api/v1/admin/backups');
  const security=useApi<{items:Array<{id:string;action:string;createdAt:string;result?:string}>;redacted:boolean}>('/api/v1/admin/security/events');
  const settings=useApi<SettingResponse>('/api/v1/admin/settings');
  const [settingValues,setSettingValues]=useState<Record<string,number>>({});
  const [diagnostics,setDiagnostics]=useState<{format:string;generatedAt:string;readOnly:boolean;checks:Array<{id:string;label:string;status:'ok'|'warning'|'error';details:unknown}>}|null>(null);
  const [diagnosticState,setDiagnosticState]=useState<ApiState>('loading');const [message,setMessage]=useState('');const [email,setEmail]=useState('');const [confirmation,setConfirmation]=useState('');const [inviteEmail,setInviteEmail]=useState('');const [invitationToken,setInvitationToken]=useState('');
  useEffect(()=>{if(settings.status==='ready'&&settings.data)setSettingValues(settings.data.values)},[settings.status,settings.data]);
  const testAll=async()=>{setDiagnosticState('loading');try{const response=await fetch('/api/v1/admin/diagnostics');if(response.status===401)throw new Error('UNAUTHENTICATED');if(!response.ok)throw new Error('HTTP');setDiagnostics(await response.json());setDiagnosticState('ready')}catch(error){setDiagnosticState(error instanceof Error&&error.message==='UNAUTHENTICATED'?'unauthenticated':'error')}};
  useEffect(()=>{void testAll()},[]);
  const request=async(path:string,method:'POST'|'PATCH'|'DELETE'='POST',body?:unknown)=>{setMessage('Traitement…');const csrf=window.localStorage.getItem('favlib-csrf')??'';const response=await fetch(path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json().catch(()=>({}));if(!response.ok){setMessage(result?.error?.message??'Action refusée.');return null}setMessage('Action terminée et auditée.');return result};
  const action=async(path:string,body:unknown={})=>{const result=await request(path,'POST',body);if(!result)return false;setMessage(result.enqueued!==undefined?`${result.enqueued} tâche(s) ajoutée(s).`:result.purged?`Purge terminée (${Object.values(result.purged as Record<string,number>).reduce((sum,value)=>sum+value,0)} élément(s)).`:'Action terminée et auditée.');await testAll();return true};
  const maintenance=async(name:'metadata-retry'|'anilist-cover-backfill'|'cover-recompress'|'purge-expired')=>{const previewResponse=await fetch(`/api/v1/admin/actions/preview?action=${name}&scope=global`);const preview=await previewResponse.json().catch(()=>null);if(!previewResponse.ok||!preview){setMessage(preview?.error?.message??'Prévisualisation impossible.');return}if(!window.confirm(`Portée globale : ${preview.count} élément(s) seront traités (total ${preview.total}). Confirmer ?`))return;await action(`/api/v1/admin/actions/${name}`,{scope:'global'})};
  const resetPersonalData=async()=>{const response=await fetch('/api/v1/admin/reset/preview');const preview=await response.json().catch(()=>null);if(!response.ok||!preview){setMessage('Prévisualisation du reset impossible.');return}if(!window.confirm(`Reset personnel : ${preview.count} élément(s) seront supprimés. Le compte, la session, les préférences et les appareils seront conservés. Confirmer ?`))return;const ok=await action('/api/v1/admin/reset',{email,confirmation});if(ok){setEmail('');setConfirmation('')}};
  const resetCatalog=async()=>{const response=await fetch('/api/v1/admin/catalog/reset/preview');const preview=await response.json().catch(()=>null);if(!response.ok||!preview){setMessage(preview?.error?.message??'Prévisualisation du reset catalogue impossible.');return}if(!window.confirm(`Reset catalogue : ${preview.media} œuvre(s), ${preview.assertions} assertion(s) et ${preview.assets} asset(s) seront concernés. Les comptes, favoris, progressions et images seront conservés. Confirmer ?`))return;await action('/api/v1/admin/catalog/reset',{confirmation:'RESET-FAVLIB-CATALOG'})};
  const download=()=>{if(!diagnostics)return;const href=URL.createObjectURL(new Blob([JSON.stringify(diagnostics,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=href;link.download=`favlib-diagnostics-${diagnostics.generatedAt.replace(/[:.]/g,'-')}.json`;link.click();URL.revokeObjectURL(href)};
  if(metrics.status!=='ready')return <div className="content"><Header eyebrow="Administration" title="Admin" subtitle="État de l’instance FavLib"/><DataState state={metrics.status}/></div>;
  const values=[['Utilisateurs',metrics.data?.users??0],['Profils actifs',metrics.data?.activeDevices??0],['Tâches en attente',metrics.data?.pendingJobs??0],['Sources à vérifier',metrics.data?.staleSnapshots??0],['Notifications non lues',metrics.data?.unreadNotifications??0]];
  const resetReady=email.toLocaleLowerCase()===session.data?.user.email.toLocaleLowerCase()&&confirmation==='RESET';
  const reload=()=>window.location.reload();
  return <div className="content"><Header eyebrow="Administration V1" title="Admin" subtitle="Configuration, sécurité, diagnostic et maintenance de l’instance FavLib" actions={<button className="button" onClick={reload}>Recharger</button>}/>
    <nav className="admin-section-nav" aria-label="Sections Admin">{[['dashboard','Vue d’ensemble'],['diagnostics','Santé'],['maintenance','Actions'],['users','Utilisateurs'],['providers','Fournisseurs'],['backups','Sauvegardes'],['security','Sécurité'],['settings','Réglages'],['catalog-reset','Reset catalogue'],['reset','Reset personnel']].map(([id,label])=><a href={`#admin-${id}`} key={id}>{label}</a>)}</nav>
    <div className="admin-metrics" id="admin-dashboard">{values.map(([label,value])=><section className="card" key={label}><span className="label">{label}</span><div className="metric">{value}</div></section>)}</div>
    <section className="card admin-panel" id="admin-users"><span className="eyebrow">Utilisateurs et invitations</span><h2>{users.data?.total??0} compte(s)</h2><div className="panel-list">{users.data?.items.map(user=><div className="panel-item" key={user.id}><div><strong>{user.email}</strong><small>{user.devices} appareil(s) · dernière synchro {user.lastSyncAt?new Date(user.lastSyncAt).toLocaleString('fr-FR'):'jamais'}</small></div><div className="admin-actions"><select className="select" aria-label={`Rôle de ${user.email}`} value={user.role} onChange={event=>void request(`/api/v1/admin/users/${user.id}`,'PATCH',{role:event.target.value}).then(reload)}><option value="member">Membre</option><option value="admin">Admin</option></select><button className="button" onClick={()=>void request(`/api/v1/admin/users/${user.id}`,'PATCH',{active:!user.active}).then(reload)}>{user.active?'Désactiver':'Activer'}</button><button className="button" onClick={()=>void request(`/api/v1/admin/users/${user.id}/revoke-sessions`).then(reload)}>Révoquer sessions</button></div></div>)}</div><form className="admin-actions" onSubmit={event=>{event.preventDefault();void request('/api/v1/admin/invitations','POST',{email:inviteEmail,expiresInHours:24}).then(result=>{if(result){setInvitationToken(result.token);setInviteEmail('')}})}}><input className="input" type="email" aria-label="E-mail invité" placeholder="membre@local" value={inviteEmail} onChange={event=>setInviteEmail(event.target.value)} required/><button className="button primary" type="submit">Créer une invitation</button></form>{invitationToken&&<p className="admin-token"><strong>Jeton affiché une seule fois :</strong> <code>{invitationToken}</code></p>}<div className="panel-list">{invitations.data?.items.map(invite=><div className="panel-item" key={invite.id}><div><strong>{invite.email}</strong><small>{invite.consumedAt?'Consommée':invite.revokedAt?'Révoquée':new Date(invite.expiresAt)<=new Date()?'Expirée':`Expire ${new Date(invite.expiresAt).toLocaleString('fr-FR')}`}</small></div>{!invite.consumedAt&&!invite.revokedAt&&<button className="button" onClick={()=>void request(`/api/v1/admin/invitations/${invite.id}`,'DELETE').then(reload)}>Révoquer</button>}</div>)}</div></section>
    <section className="card admin-panel" id="admin-providers"><span className="eyebrow">Fournisseurs et sources</span><h2>Politiques et connecteurs</h2><div className="diagnostic-list">{providers.data?.items.map(provider=><article className="diagnostic-row" key={provider.provider}><span className={`badge ${provider.status==='AUTHORIZED'?'available':'review'}`}>{provider.status}</span><div><strong>{provider.provider} · {provider.version}</strong><small>{provider.attribution??'Aucune attribution configurée'} · dernier résultat {provider.lastResult??'NOT_VERIFIED'}{provider.backoffUntil?` · backoff jusqu’au ${new Date(provider.backoffUntil).toLocaleString('fr-FR')}`:''}</small></div></article>)}{sources.data?.items.map(source=><article className="diagnostic-row" key={source.id}><span className={`badge ${source.state==='ACTIVE'?'available':'review'}`}>{source.state}</span><div><strong>{source.id} · {source.domain}</strong><small>Version active {source.activeVersion??'aucune'} · {source.versions.length} version(s)</small></div></article>)}</div></section>
    <section className="card admin-panel" id="admin-backups"><div className="admin-panel-head"><div><span className="eyebrow">Sauvegardes</span><h2>Destination gérée par le serveur</h2></div><button className="button primary" onClick={()=>void request('/api/v1/admin/backups').then(reload)}>Demander une sauvegarde</button></div><div className="panel-list">{backups.data?.items.map(backup=><div className="panel-item" key={backup.id}><div><strong>{backup.status} · {new Date(backup.requestedAt).toLocaleString('fr-FR')}</strong><small>Checksum {backup.checksum??'NOT_VERIFIED'} · RPO {backup.rpo} · RTO {backup.rto}</small></div></div>)}</div></section>
    <section className="card admin-panel" id="admin-security"><span className="eyebrow">Sécurité</span><h2>Événements expurgés</h2><p>Aucune URL ni aucun contenu de favori n’est inclus.</p><div className="panel-list">{security.data?.items.slice(0,20).map(event=><div className="panel-item" key={event.id}><div><strong>{event.action}</strong><small>{new Date(event.createdAt).toLocaleString('fr-FR')} · {event.result??'audité'}</small></div></div>)}</div></section>
    <section className="card admin-panel" id="admin-settings"><span className="eyebrow">Réglages opérationnels</span><h2>Valeurs bornées et persistantes</h2><div className="settings-list">{Object.entries(settingValues).map(([key,value])=><label className="setting-row" key={key}><span>{key}</span><input className="input" type="number" value={value} onChange={event=>setSettingValues(current=>({...current,[key]:Number(event.target.value)}))}/><small>Défaut : {settings.data?.defaults[key]}</small></label>)}</div><button className="button primary" onClick={()=>void request('/api/v1/admin/settings','PATCH',settingValues)}>Enregistrer les réglages</button></section>
    <section className="card admin-panel" id="admin-diagnostics"><div className="admin-panel-head"><div><span className="eyebrow">Diagnostics non destructifs</span><h2>Santé et cohérence</h2></div><div><button className="button primary" onClick={()=>void testAll()}>Tout tester</button> <button className="button" disabled={!diagnostics} onClick={download}>Rapport JSON</button></div></div>{diagnosticState!=='ready'?<DataState state={diagnosticState}/>:<div className="diagnostic-list">{diagnostics?.checks.map(check=><article className="diagnostic-row" key={check.id}><span className={`badge ${check.status==='ok'?'available':check.status==='warning'?'review':'error'}`}>{check.status}</span><div><strong>{check.label}</strong><small>{JSON.stringify(check.details)}</small></div></article>)}</div>}</section>
    <section className="card admin-panel" id="admin-maintenance"><span className="eyebrow">Maintenance bornée</span><h2>Portée globale explicite</h2><p>Les fournisseurs ne sont jamais sondés par les diagnostics. Une prévisualisation annonce le nombre avant confirmation.</p><div className="admin-actions"><button className="button" onClick={()=>void maintenance('metadata-retry')}>Relancer métadonnées</button><button className="button" onClick={()=>void maintenance('anilist-cover-backfill')}>Backfill couvertures catalogue</button><button className="button" onClick={()=>void maintenance('cover-recompress')}>Recompresser couvertures</button><button className="button" onClick={()=>void maintenance('purge-expired')}>Purger les expirations</button></div>{message&&<p role="status">{message}</p>}</section>
    <section className="card admin-panel danger-zone" id="admin-catalog-reset"><span className="eyebrow">Reset catalogue</span><h2>Reconstruire le catalogue</h2><p>Supprime les œuvres, titres, identités et métadonnées pour permettre une resynchronisation propre. Les comptes, favoris, appareils, progressions et images locales sont conservés.</p><button className="button danger" onClick={()=>void resetCatalog()}>Prévisualiser puis reset catalogue</button></section>
    <section className="card admin-panel danger-zone" id="admin-reset"><span className="eyebrow">Reset personnel</span><h2>Réinitialiser mes données FavLib</h2><p>Le compte, la session, les préférences et les appareils sont conservés. Les reçus d’inventaire sont invalidés pour permettre un réimport idempotent.</p><div className="reset-fields"><input className="input" aria-label="E-mail de confirmation du reset" placeholder={session.data?.user.email??'E-mail admin'} value={email} onChange={event=>setEmail(event.target.value)}/><input className="input" aria-label="Mot de confirmation du reset" placeholder="RESET" value={confirmation} onChange={event=>setConfirmation(event.target.value)}/><button className="button danger" disabled={!resetReady} onClick={()=>void resetPersonalData()}>Prévisualiser puis réinitialiser</button></div></section>
  </div>;
}

export function FavLibApp() {
  const path = currentPath();
  const view = path === '/library' ? <Library /> : path.startsWith('/library/') ? <Detail id={decodeURIComponent(path.slice('/library/'.length))} /> : path === '/calendar' ? <Calendar /> : path === '/settings' ? <Settings /> : path === '/admin'?<Admin/>:<Home />;
  return <Shell>{view}</Shell>;
}
